516		}
517		if *account != "" {
518			// 未出现过的账户余额为 0，且不向状态文件新增账户记录。
519			balance := snapshot.Balances[*account]
520			if cf.asJSON {
521				emitJSON(map[string]any{"treasury": snapshot.Treasury, "account": *account, "balance": balance})
522			} else {
523				fmt.Printf("treasury %d\n%s %d\n", snapshot.Treasury, *account, balance)
524			}
525			return
526		}
527		if cf.asJSON {
528			emitJSON(map[string]any{"treasury": snapshot.Treasury, "balances": snapshot.Balances})
529			return
530		}
531		fmt.Printf("treasury %d\n", snapshot.Treasury)
532		accounts := make([]string, 0, len(snapshot.Balances))
533		for acct := range snapshot.Balances {
534			accounts = append(accounts, acct)
535		}
536		sort.Strings(accounts)
537		for _, acct := range accounts {
538			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
539		}
