582	func runProposals(args []string) {
583		cf := newCmdFlags("proposals")
584		cf.parse(args)
585		store, err := govflow.Open(cf.state)
586		if err != nil {
587			fail(err)
588		}
589		defer store.Close()
590		// 一次快照读取保证登记提案与投票提案来自同一份已提交状态，
591		// 不会把并发执行前后的提案状态拼在一起。
592		snapshot, err := store.ProposalsSnapshot()
593		if err != nil {
594			fail(err)
595		}
596		registered := snapshot.Registered
597		voting := snapshot.Voting
598		if cf.asJSON {
599			// 保持既有 JSON 形状：一个数组；登记记录字段不变，投票提案带额外字段。
600			merged := make([]any, 0, len(registered)+len(voting))
601			for _, r := range registered {
602				merged = append(merged, r)
603			}
604			for _, v := range voting {
605				merged = append(merged, v)
606			}
607			emitJSON(merged)
608			return
609		}
610		for _, record := range registered {
611			printProposalText(record)
612		}
613		for _, view := range voting {
614			printVoteProposalText(view)
615		}
616	}
