666	func printProposalText(p govflow.ProposalRecord) {
667		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
668		for i, action := range p.Actions {
669			fmt.Printf("  action %d: %s\n", i, action)
670		}
