package govflow

import (
	"bytes"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// buildCLI 将命令行编译到临时目录，供跨进程测试使用。仅使用标准库，离线可编译。
func buildCLI(t *testing.T) string {
	t.Helper()
	binary := filepath.Join(t.TempDir(), "govflow")
	cmd := exec.Command("go", "build", "-o", binary, "./cmd/govflow")
	// 测试工作目录为模块下的 govflow/，仓库根目录在上一层。
	cmd.Dir = ".."
	var out bytes.Buffer
	cmd.Stderr = &out
	if err := cmd.Run(); err != nil {
		t.Fatalf("build cli: %v\n%s", err, out.String())
	}
	return binary
}

func runCLI(t *testing.T, binary, state string, args ...string) (stdout, stderr string, code int) {
	t.Helper()
	// main 以第一个参数作为子命令，--state 必须位于子命令之后。
	full := append([]string{args[0], "--state", state}, args[1:]...)
	cmd := exec.Command(binary, full...)
	var so, se bytes.Buffer
	cmd.Stdout = &so
	cmd.Stderr = &se
	err := cmd.Run()
	if ee, ok := err.(*exec.ExitError); ok {
		code = ee.ExitCode()
	} else if err != nil {
		t.Fatalf("run cli %v: %v", args, err)
	}
	return so.String(), se.String(), code
}

// TestCrossProcessSameProposal：多个进程同时执行同一提案，
// 只能有一份成功凭据；其余进程拿到同一份凭据（重试语义），不得二次扣款。
func TestCrossProcessSameProposal(t *testing.T) {
	binary := buildCLI(t)
	state := filepath.Join(t.TempDir(), "treasury.json")
	if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
		t.Fatal("init failed")
	}
	if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-1",
		"--timelock", "100", "--action", "transfer:audits:250"); code != 0 {
		t.Fatal("register failed")
	}

	const n = 16
	var wg sync.WaitGroup
	codes := make([]int, n)
	outputs := make([]string, n)
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			so, se, code := runCLI(t, binary, state, "execute", "--id", "gip-1",
				"--now", strconv.Itoa(100+i), "--json")
			codes[i] = code
			outputs[i] = so + se
		}(i)
	}
	close(start)
	wg.Wait()

	for i, code := range codes {
		if code != 0 {
			t.Fatalf("process %d exited %d: %s", i, code, outputs[i])
		}
		// 每个进程看到的首次执行时间都必须是 100（最早请求未必胜出，但凭据唯一）。
		if !strings.Contains(outputs[i], `"executed_at"`) {
			t.Fatalf("process %d got no receipt: %s", i, outputs[i])
		}
	}
	so, _, code := runCLI(t, binary, state, "receipts", "--json")
	if code != 0 {
		t.Fatal("receipts failed")
	}
	if strings.Count(so, `"proposal_id"`) != 1 {
		t.Fatalf("expected exactly one receipt, got:\n%s", so)
	}
	if so2, _, _ := runCLI(t, binary, state, "balances", "--json"); !strings.Contains(so2, `"treasury": 750`) {
		t.Fatalf("treasury must be 750 after single execution:\n%s", so2)
	}
}

// TestCrossProcessDifferentProposals：40 个进程各花 10，资金库只有 100，
// 必须恰好 10 个成功，且所有判断基于实际已提交余额。
func TestCrossProcessDifferentProposals(t *testing.T) {
	binary := buildCLI(t)
	state := filepath.Join(t.TempDir(), "treasury.json")
	if _, _, code := runCLI(t, binary, state, "init", "--balance", "100"); code != 0 {
		t.Fatal("init failed")
	}
	const n = 40
	for i := 0; i < n; i++ {
		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-"+itoa(i),
			"--timelock", "0", "--action", "transfer:acct:10"); code != 0 {
			t.Fatalf("register %d failed", i)
		}
	}

	var wg sync.WaitGroup
	successes := make(chan int, n)
	failures := make(chan string, n)
	start := make(chan struct{})

	stored := &storedVoteProposal{
		ID:          in.ID,
		State:       "voting",
		Members:     make([]storedMember, 0, len(in.Members)),
		Delegations: make([]storedDelegation, 0, len(in.Delegations)),
		Quorum:      in.Quorum,
		StartAt:     in.StartAt,
		Deadline:    in.Deadline,
		TimelockEnd: in.TimelockEnd,
		Actions:     copyActions(in.Actions),
		Ballots:     []storedBallot{},
	}
	for _, m := range in.Members {
		stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
	}
	for _, d := range in.Delegations {
		stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
	}
	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
	// delegations/ballots 判定时不会把本进程新建的提案误判为字段缺失。
	// 创建时不提供委托、尚无投票都是合法的：空数组明确写出即表示无人委托、
	// 无人投票。
	stored.delegationsRaw, _ = json.Marshal(stored.Delegations)
	stored.ballotsRaw, _ = json.Marshal(stored.Ballots)
	state.VoteProposals[in.ID] = stored
	if err := s.commitLocked(state); err != nil {
		return nil, false, err
	}
	return voteProposalView(stored), false, nil
}

func voteReject(reason string) error {
	return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
}

func tallyReject(reason string) error {
	return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
}

// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----

// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
type ballotCounts struct {
	forWeight     int64
	againstWeight int64
}

// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
func (c ballotCounts) turnout() (int64, bool) {
	return addInt64(c.forWeight, c.againstWeight)
}

